import React, { useState, useEffect } from 'react';
import api from '../services/api';
import Swal from 'sweetalert2';

const CrearOferta = ({ tipo, onClose, onSuccess }) => {
  const [activeTab, setActiveTab] = useState('programa');
  const [busquedaPrograma, setBusquedaPrograma] = useState('');
  const [mostrarListaPrograma, setMostrarListaPrograma] = useState(false);
  const [loading, setLoading] = useState(false);
  const [referencias, setReferencias] = useState({
    programas: [],
    modalidades: [],
    tiposProg: [],
    tiposOferta: [],
    municipios: []
  });

  // Obtener usuario del localStorage
  const user = JSON.parse(localStorage.getItem('user') || '{}');

  const [formData, setFormData] = useState({
    programa_formacion: '',
    modalidad: '',
    duracion_meses: 4,
    es_campesena: tipo === 'campesena',
    tipo_programa: '',
    tipo_oferta: '',
    cupo_maximo: '',
    ambiente: { nombre: '' },
    fechas: { inicio: '', fin: '' },
    ubicacion: { departamento: 'Cauca', municipio: '', direccion: '' },
    empresa_solicitante: {
      nombre: '',
      fecha_creacion: '',
      direccion: '',
      nit: '',
      numero_empleados: '',
      tipo_empresa: 'Privada',
      representante_legal: { nombre: '', documento: '', correo: '' },
      contacto_empresa: { nombre: '', cargo: '', correo: '' }
    },
    subsector_economico: { nombre: '' },
    programa_especial: '',
    convenio: { nombre: '' },
    horario: { hora_inicio: '', hora_fin: '', dias: [] },
    firma_digital: { tipo: 'electronica' },
    coordinador_asignado: user?.coordinadorAsignado?._id || '',
    carta_pdf_file: null
  });

  // Cargar referencias
  useEffect(() => {
    cargarReferencias();
  }, []);

  const cargarReferencias = async () => {
    try {
      const [programasRes, modalidadesRes, tiposProgRes, tiposOfertaRes, municipiosRes] = await Promise.all([
        api.get('/programas-formacion'),
        api.get('/modalidades'),
        api.get('/tipos-programa'),
        api.get('/tipos-oferta'),
        api.get('/municipios')
      ]);
      setReferencias({
        programas: programasRes.data.data || [],
        modalidades: modalidadesRes.data.data || [],
        tiposProg: tiposProgRes.data.data || [],
        tiposOferta: tiposOfertaRes.data.data || [],
        municipios: municipiosRes.data.data || []
      });
    } catch (error) {
      console.error('Error cargando referencias:', error);
      Swal.fire({ icon: 'error', title: 'Error', text: 'No se pudieron cargar los datos iniciales' });
    }
  };

  // Al seleccionar programa, autocompletar tipo_programa y horas
  useEffect(() => {
    if (!formData.programa_formacion || !referencias.programas.length) return;
    const programaSeleccionado = referencias.programas.find(p => p._id === formData.programa_formacion);
    if (!programaSeleccionado) return;

    // Asignar horas
    const horas = programaSeleccionado.duracion_maxima;
    if (horas && typeof horas === 'number') {
      setFormData(prev => ({ ...prev, duracion_meses: horas }));
    }

    // Autocompletar tipo de programa
    const tipoTexto = programaSeleccionado.tipo_programa?.trim();
    if (tipoTexto) {
      const tipoEncontrado = referencias.tiposProg.find(t =>
        t.nombre && t.nombre.trim().toLowerCase() === tipoTexto.toLowerCase()
      );
      if (tipoEncontrado) {
        setFormData(prev => ({ ...prev, tipo_programa: tipoEncontrado._id }));
      } else {
        Swal.fire({ icon: 'warning', title: 'Advertencia', text: `El programa tiene tipo "${tipoTexto}" pero no existe en la lista.` });
      }
    }
  }, [formData.programa_formacion, referencias.programas, referencias.tiposProg]);

  // Calcular fecha fin automáticamente
  const calcularFechaFin = (fechaInicio, horasPrograma, horaInicio, horaFin, diasSemana) => {
    if (!fechaInicio || !horasPrograma || !horaInicio || !horaFin || diasSemana.length === 0) return null;
    const [hIni, mIni] = horaInicio.split(':').map(Number);
    const [hFin, mFin] = horaFin.split(':').map(Number);
    const horasPorDia = (hFin * 60 + mFin - (hIni * 60 + mIni)) / 60;
    if (horasPorDia <= 0) return null;

    const mapaDia = { 'Domingo': 0, 'Lunes': 1, 'Martes': 2, 'Miércoles': 3, 'Jueves': 4, 'Viernes': 5, 'Sábado': 6 };
    const numeroDias = diasSemana.map(d => mapaDia[d]).filter(n => n !== undefined);
    let horasAcumuladas = 0;
    let fechaActual = new Date(fechaInicio + 'T00:00:00');
    let iter = 0;
    while (horasAcumuladas < horasPrograma && iter < 3650) {
      if (numeroDias.includes(fechaActual.getDay())) horasAcumuladas += horasPorDia;
      if (horasAcumuladas < horasPrograma) fechaActual.setDate(fechaActual.getDate() + 1);
      iter++;
    }
    return fechaActual.toISOString().split('T')[0];
  };

  useEffect(() => {
    if (formData.es_campesena) return;
    const horasPrograma = formData.duracion_meses;
    if (!horasPrograma) return;
    const fechaFin = calcularFechaFin(
      formData.fechas.inicio,
      horasPrograma,
      formData.horario.hora_inicio,
      formData.horario.hora_fin,
      formData.horario.dias
    );
    if (fechaFin && formData.fechas.inicio) {
      setFormData(prev => ({ ...prev, fechas: { ...prev.fechas, fin: fechaFin } }));
    }
  }, [formData.fechas.inicio, formData.horario.hora_inicio, formData.horario.hora_fin, formData.horario.dias, formData.duracion_meses]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name.includes('.')) {
      const [parent, child, subchild] = name.split('.');
      if (subchild) {
        setFormData(prev => ({
          ...prev,
          [parent]: { ...prev[parent], [child]: { ...prev[parent][child], [subchild]: value } }
        }));
      } else {
        setFormData(prev => ({ ...prev, [parent]: { ...prev[parent], [child]: value } }));
      }
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  const getTipoOfertaNombre = () => {
    const tipo = referencias.tiposOferta?.find(t => t._id === formData.tipo_oferta);
    return tipo ? tipo.nombre : '';
  };

  const validateTab = () => {
    if (activeTab === 'programa') {
      if (!formData.programa_formacion) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Selecciona un programa de formación' }); return false; }
      if (!formData.modalidad) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Selecciona una modalidad' }); return false; }
      if (!formData.duracion_meses) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'El programa debe tener horas registradas' }); return false; }
      if (!formData.tipo_programa) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'El tipo de programa no se pudo determinar' }); return false; }
      return true;
    }
    if (activeTab === 'oferta') {
      if (!formData.tipo_oferta) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Selecciona un tipo de oferta' }); return false; }
      if (!formData.cupo_maximo) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa el cupo máximo' }); return false; }
      if (!formData.subsector_economico.nombre) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa el subsector económico' }); return false; }
      if (!formData.convenio.nombre) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa el nombre del convenio' }); return false; }
      if (!formData.coordinador_asignado) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'No tienes un coordinador asignado' }); return false; }
      if (getTipoOfertaNombre() === 'Cerrada') {
        if (!formData.empresa_solicitante.nombre) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa el nombre de la empresa' }); return false; }
        if (!formData.empresa_solicitante.nit) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa el NIT de la empresa' }); return false; }
      }
      return true;
    }
    if (activeTab === 'ubicacion') {
      if (!formData.ubicacion.municipio) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Selecciona un municipio' }); return false; }
      if (!formData.ubicacion.direccion) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa la dirección' }); return false; }
      if (!formData.ambiente.nombre) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa el nombre del ambiente' }); return false; }
      return true;
    }
    if (activeTab === 'horario') {
      if (!formData.fechas.inicio) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa la fecha de inicio' }); return false; }
      if (!formData.fechas.fin) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa la fecha de fin' }); return false; }
      if (new Date(formData.fechas.inicio) >= new Date(formData.fechas.fin)) {
        Swal.fire({ icon: 'warning', title: 'Fechas inválidas', text: 'La fecha de fin debe ser posterior a la de inicio' });
        return false;
      }
      if (!formData.es_campesena) {
        if (formData.horario.dias.length === 0) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Agrega al menos un día de clase' }); return false; }
        if (!formData.horario.hora_inicio || !formData.horario.hora_fin) { Swal.fire({ icon: 'warning', title: 'Campo requerido', text: 'Ingresa la hora de inicio y fin' }); return false; }
      }
      return true;
    }
    return true;
  };

  const nextTab = () => {
    if (validateTab()) {
      const tabs = ['programa', 'oferta', 'ubicacion', 'horario'];
      const nextIndex = tabs.indexOf(activeTab) + 1;
      if (nextIndex < tabs.length) setActiveTab(tabs[nextIndex]);
    }
  };

  const prevTab = () => {
    const tabs = ['programa', 'oferta', 'ubicacion', 'horario'];
    const prevIndex = tabs.indexOf(activeTab) - 1;
    if (prevIndex >= 0) setActiveTab(tabs[prevIndex]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateTab()) return;

    const datosEnvio = { ...formData, tipo_oferta_nombre: getTipoOfertaNombre() };
    setLoading(true);

    try {
      const formDataToSend = new FormData();
      Object.keys(datosEnvio).forEach(key => {
        if (key === 'carta_pdf_file' && datosEnvio[key]) formDataToSend.append(key, datosEnvio[key]);
        else if (typeof datosEnvio[key] === 'object') formDataToSend.append(key, JSON.stringify(datosEnvio[key]));
        else formDataToSend.append(key, datosEnvio[key]);
      });
      await api.post('/ofertas', formDataToSend, { headers: { 'Content-Type': 'multipart/form-data' } });
      Swal.fire({ icon: 'success', title: '¡Oferta creada!', text: 'La oferta se ha guardado exitosamente', timer: 2000, showConfirmButton: false });
      if (onSuccess) onSuccess();
      else if (onClose) onClose();
      else window.location.href = '/ofertas/mis-ofertas';
    } catch (error) {
      console.error(error);
      Swal.fire({ icon: 'error', title: 'Error', text: error.response?.data?.message || 'Error al crear la oferta' });
    } finally {
      setLoading(false);
    }
  };

  // Componente de pestaña
  const TabButton = ({ tab, label }) => (
    <button
      type="button"
      onClick={() => setActiveTab(tab)}
      className={`flex-1 py-4 text-center font-bold uppercase tracking-wide transition-all duration-200 rounded-t-2xl ${
        activeTab === tab
          ? 'text-white bg-gradient-to-r from-[#00643C] to-[#004d2e] shadow-lg'
          : 'text-gray-500 hover:text-[#00643C] hover:bg-gray-50'
      }`}
    >
      {label}
    </button>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#e8f5e9] to-[#c8e6d9] py-8 px-4 font-['Segoe_UI','Roboto',sans-serif]">
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-3xl shadow-2xl overflow-hidden transition-all duration-300 hover:shadow-3xl">
          {/* Header */}
          <div className="bg-gradient-to-r from-[#00643C] to-[#004d2e] p-6 text-white">
            <div className="flex items-center gap-4">
              <img src="/logosena.png" alt="SENA" className="h-12 w-auto filter brightness-0 invert" />
              <div>
                <h1 className="text-3xl font-bold">Nueva Oferta</h1>
                <p className="text-[#FFD966] font-medium">
                  Tipo: {tipo === 'campesena' ? 'Campesena' : 'Regular'}
                </p>
              </div>
            </div>
          </div>

          {/* Pestañas */}
          <div className="flex border-b border-gray-100 bg-gray-50/50">
            <TabButton tab="programa" label="Programa" />
            <TabButton tab="oferta" label="Oferta" />
            <TabButton tab="ubicacion" label="Ubicación" />
            <TabButton tab="horario" label="Horario" />
          </div>

          {/* Formulario */}
          <form onSubmit={handleSubmit} className="p-8">
            {/* Tab Programa */}
            {activeTab === 'programa' && (
              <div className="space-y-6">
                <div className="relative">
                  <label className="block font-semibold text-gray-700 mb-2">Programa de formación *</label>
                  <div className="relative">
                    <input
                      type="text"
                      placeholder="Buscar programa por nombre o código..."
                      value={busquedaPrograma}
                      onChange={e => {
                        const val = e.target.value;
                        setBusquedaPrograma(val);
                        setMostrarListaPrograma(true);
                        if (formData.programa_formacion) setFormData(prev => ({ ...prev, programa_formacion: '' }));
                      }}
                      onFocus={() => setMostrarListaPrograma(true)}
                      onBlur={() => setTimeout(() => setMostrarListaPrograma(false), 200)}
                      className={`w-full p-3 border-2 rounded-2xl pr-10 transition-all focus:border-[#00643C] focus:ring-2 focus:ring-[#00643C]/20 outline-none ${
                        formData.programa_formacion ? 'border-green-400 bg-green-50' : 'border-gray-200'
                      }`}
                      autoComplete="off"
                    />
                    {formData.programa_formacion ? (
                      <span className="absolute right-3 top-3.5 text-green-600 text-xl">✓</span>
                    ) : busquedaPrograma && (
                      <span className="absolute right-3 top-3.5 text-gray-400">🔍</span>
                    )}
                  </div>
                  {formData.programa_formacion && (
                    <div className="flex justify-between mt-2">
                      <p className="text-xs text-green-700 font-medium">Programa seleccionado</p>
                      <button
                        type="button"
                        onClick={() => { setBusquedaPrograma(''); setFormData(prev => ({ ...prev, programa_formacion: '', tipo_programa: '', duracion_meses: 4 })); }}
                        className="text-xs text-red-400 hover:text-red-600"
                      >
                        ✕ Limpiar
                      </button>
                    </div>
                  )}
                  {mostrarListaPrograma && busquedaPrograma.length > 0 && (
                    <ul className="absolute z-50 w-full bg-white border border-gray-200 rounded-xl shadow-lg max-h-64 overflow-y-auto mt-1">
                      {referencias.programas
                        .filter(p => p.nombre_programa?.toLowerCase().includes(busquedaPrograma.toLowerCase()))
                        .slice(0, 50)
                        .map(p => (
                          <li
                            key={p._id}
                            onMouseDown={e => {
                              e.preventDefault();
                              setFormData(prev => ({ ...prev, programa_formacion: p._id }));
                              setBusquedaPrograma(p.nombre_programa);
                              setMostrarListaPrograma(false);
                            }}
                            className={`px-4 py-3 cursor-pointer hover:bg-green-50 text-sm ${
                              formData.programa_formacion === p._id ? 'bg-green-100 font-semibold text-green-800' : 'text-gray-700'
                            }`}
                          >
                            {p.nombre_programa}
                          </li>
                        ))}
                      {!referencias.programas.some(p => p.nombre_programa?.toLowerCase().includes(busquedaPrograma.toLowerCase())) && (
                        <li className="px-4 py-3 text-gray-400 text-sm text-center">Sin resultados</li>
                      )}
                    </ul>
                  )}
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Modalidad *</label>
                  <select name="modalidad" value={formData.modalidad} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" required>
                    <option value="">Selecciona</option>
                    {referencias.modalidades?.map(m => <option key={m._id} value={m._id}>{m.nombre}</option>)}
                  </select>
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Horas del programa *</label>
                  <input type="number" value={formData.duracion_meses} className="w-full p-3 border-2 border-gray-200 rounded-2xl bg-gray-100" disabled />
                  <p className="text-xs text-gray-400 mt-1">Cargadas automáticamente desde el programa de formación</p>
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Tipo de programa *</label>
                  <select value={formData.tipo_programa} className="w-full p-3 border-2 border-gray-200 rounded-2xl bg-gray-100" disabled>
                    <option value="">Selecciona</option>
                    {referencias.tiposProg?.map(t => <option key={t._id} value={t._id}>{t.nombre}</option>)}
                  </select>
                  <p className="text-xs text-gray-400 mt-1">Se asigna automáticamente según el programa</p>
                </div>
              </div>
            )}

            {/* Tab Oferta */}
            {activeTab === 'oferta' && (
              <div className="space-y-6">
                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Tipo de oferta *</label>
                  <select name="tipo_oferta" value={formData.tipo_oferta} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" required>
                    <option value="">Selecciona</option>
                    {referencias.tiposOferta?.filter(t => ['Cerrada', 'Pública', 'Publica'].includes(t.nombre)).map(t => (
                      <option key={t._id} value={t._id}>{t.nombre}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Cupo máximo *</label>
                  <input type="number" name="cupo_maximo" value={formData.cupo_maximo} onChange={handleChange} min="1" className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Subsector económico *</label>
                  <input type="text" name="subsector_economico.nombre" value={formData.subsector_economico.nombre} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Convenio *</label>
                  <input type="text" name="convenio.nombre" value={formData.convenio.nombre} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                </div>

                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Coordinador asignado</label>
                  <input type="text" value={user?.coordinadorAsignado?.nombre || 'No asignado'} disabled className="w-full p-3 border-2 border-gray-200 rounded-2xl bg-gray-100" />
                </div>

                {getTipoOfertaNombre() === 'Cerrada' && (
                  <div className="mt-6 p-6 border-2 border-[#FFD966] rounded-2xl bg-[#FFFBEB]">
                    <h3 className="text-xl font-bold text-[#00643C] mb-4">Datos de la empresa patrocinadora</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div><label className="block font-semibold mb-1">Nombre de la Empresa *</label><input type="text" name="empresa_solicitante.nombre" value={formData.empresa_solicitante.nombre} onChange={handleChange} className="w-full p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" /></div>
                      <div><label className="block font-semibold mb-1">Fecha Creación</label><input type="date" name="empresa_solicitante.fecha_creacion" value={formData.empresa_solicitante.fecha_creacion?.split('T')[0] || ''} onChange={handleChange} className="w-full p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" /></div>
                      <div><label className="block font-semibold mb-1">Dirección</label><input type="text" name="empresa_solicitante.direccion" value={formData.empresa_solicitante.direccion} onChange={handleChange} className="w-full p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" /></div>
                      <div><label className="block font-semibold mb-1">NIT</label><input type="text" name="empresa_solicitante.nit" value={formData.empresa_solicitante.nit} onChange={handleChange} className="w-full p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" /></div>
                      <div><label className="block font-semibold mb-1">Número de Empleados</label><input type="number" name="empresa_solicitante.numero_empleados" value={formData.empresa_solicitante.numero_empleados} onChange={handleChange} className="w-full p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" /></div>
                      <div><label className="block font-semibold mb-1">Tipo de Empresa</label><select name="empresa_solicitante.tipo_empresa" value={formData.empresa_solicitante.tipo_empresa} onChange={handleChange} className="w-full p-3 border-2 rounded-xl focus:border-[#00643C] outline-none"><option value="Privada">Privada</option><option value="Pública">Pública</option><option value="Mixta">Mixta</option><option value="Sin ánimo de lucro">Sin ánimo de lucro</option></select></div>
                    </div>
                    <h4 className="font-semibold mt-4 mb-2 text-[#004d2e]">Representante Legal</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <input type="text" name="empresa_solicitante.representante_legal.nombre" value={formData.empresa_solicitante.representante_legal.nombre} onChange={handleChange} placeholder="Nombre completo" className="p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" />
                      <input type="text" name="empresa_solicitante.representante_legal.documento" value={formData.empresa_solicitante.representante_legal.documento} onChange={handleChange} placeholder="Documento" className="p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" />
                      <input type="email" name="empresa_solicitante.representante_legal.correo" value={formData.empresa_solicitante.representante_legal.correo} onChange={handleChange} placeholder="Correo" className="p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" />
                    </div>
                    <h4 className="font-semibold mt-4 mb-2 text-[#004d2e]">Contacto en la Empresa</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <input type="text" name="empresa_solicitante.contacto_empresa.nombre" value={formData.empresa_solicitante.contacto_empresa.nombre} onChange={handleChange} placeholder="Nombre del contacto" className="p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" />
                      <input type="text" name="empresa_solicitante.contacto_empresa.cargo" value={formData.empresa_solicitante.contacto_empresa.cargo} onChange={handleChange} placeholder="Cargo" className="p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" />
                      <input type="email" name="empresa_solicitante.contacto_empresa.correo" value={formData.empresa_solicitante.contacto_empresa.correo} onChange={handleChange} placeholder="Correo" className="p-3 border-2 rounded-xl focus:border-[#00643C] outline-none" />
                    </div>
                    <div className="mt-4">
                      <label className="block font-semibold mb-1">Carta de la empresa (PDF)</label>
                      <input type="file" accept="application/pdf" onChange={(e) => setFormData(prev => ({ ...prev, carta_pdf_file: e.target.files[0] }))} className="w-full p-2 border-2 rounded-xl" />
                      {formData.carta_pdf_file && <p className="text-sm text-green-600 mt-1">Archivo seleccionado: {formData.carta_pdf_file.name}</p>}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Tab Ubicación */}
            {activeTab === 'ubicacion' && (
              <div className="space-y-6">
                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Departamento</label>
                  <input type="text" name="ubicacion.departamento" value={formData.ubicacion.departamento} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                </div>
                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Municipio *</label>
                  <select name="ubicacion.municipio" value={formData.ubicacion.municipio} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" required>
                    <option value="">Selecciona</option>
                    {referencias.municipios?.map(m => <option key={m._id} value={m._id}>{m.nombre}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Dirección *</label>
                  <input type="text" name="ubicacion.direccion" value={formData.ubicacion.direccion} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                </div>
                <div>
                  <label className="block font-semibold text-gray-700 mb-2">Ambiente (nombre) *</label>
                  <input type="text" name="ambiente.nombre" value={formData.ambiente.nombre} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                </div>
              </div>
            )}

            {/* Tab Horario */}
            {activeTab === 'horario' && (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block font-semibold text-gray-700 mb-2">Fecha de inicio *</label>
                    <input type="date" name="fechas.inicio" value={formData.fechas.inicio} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" />
                  </div>
                  <div>
                    <label className="block font-semibold text-gray-700 mb-2">Fecha de fin *</label>
                    <input type="date" name="fechas.fin" value={formData.fechas.fin} onChange={handleChange} className={`w-full p-3 border-2 rounded-2xl focus:border-[#00643C] outline-none ${formData.fechas.fin && formData.horario.hora_inicio && formData.horario.dias.length ? 'bg-green-50 border-green-300' : 'border-gray-200'}`} />
                  </div>
                </div>

                {!formData.es_campesena && (
                  <>
                    <div className="grid grid-cols-2 gap-4">
                      <div><label className="block font-semibold text-gray-700 mb-2">Hora inicio</label><input type="time" name="horario.hora_inicio" value={formData.horario.hora_inicio} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" /></div>
                      <div><label className="block font-semibold text-gray-700 mb-2">Hora fin</label><input type="time" name="horario.hora_fin" value={formData.horario.hora_fin} onChange={handleChange} className="w-full p-3 border-2 border-gray-200 rounded-2xl focus:border-[#00643C] outline-none" /></div>
                    </div>
                    <div>
                      <label className="block font-semibold text-gray-700 mb-2">Días de clase</label>
                      <div className="flex flex-wrap gap-2">
                        {['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'].map(dia => {
                          const activo = formData.horario.dias.includes(dia);
                          return (
                            <button
                              key={dia}
                              type="button"
                              onClick={() => {
                                setFormData(prev => ({
                                  ...prev,
                                  horario: { ...prev.horario, dias: activo ? prev.horario.dias.filter(d => d !== dia) : [...prev.horario.dias, dia] }
                                }));
                              }}
                              className={`flex flex-col items-center justify-center w-16 h-16 rounded-2xl font-bold text-sm transition-all border-2 select-none ${
                                activo ? 'bg-[#00643C] text-white border-[#00643C] shadow-md scale-105' : 'bg-white text-gray-500 border-gray-200 hover:border-[#00643C] hover:text-[#00643C]'
                              }`}
                            >
                              <span className="text-lg">{dia.substring(0, 2)}</span>
                              <span className="text-[10px] font-normal">{dia}</span>
                            </button>
                          );
                        })}
                      </div>
                      {formData.horario.dias.length > 0 && (
                        <p className="text-xs text-gray-500 mt-2">Seleccionados: <span className="font-semibold text-green-700">{formData.horario.dias.join(', ')}</span></p>
                      )}
                    </div>
                    {formData.horario.hora_inicio && formData.horario.hora_fin && formData.horario.dias.length > 0 && (() => {
                      const horasPrograma = formData.duracion_meses;
                      const [hIni, mIni] = formData.horario.hora_inicio.split(':').map(Number);
                      const [hFin, mFin] = formData.horario.hora_fin.split(':').map(Number);
                      const horasPorDia = ((hFin * 60 + mFin) - (hIni * 60 + mIni)) / 60;
                      const horasPorSemana = horasPorDia * formData.horario.dias.length;
                      const semanasTotal = horasPrograma ? Math.ceil(horasPrograma / horasPorSemana) : null;
                      const mesesTotal = semanasTotal ? (semanasTotal / 4.33).toFixed(1) : null;
                      if (horasPorDia <= 0) return null;
                      return (
                        <div className="bg-[#FFFBEB] border-2 border-[#FFD966] rounded-2xl p-4">
                          <p className="text-sm font-semibold text-[#00643C] mb-2">📊 Resumen del cálculo</p>
                          <div className="grid grid-cols-2 gap-2 text-sm text-gray-700">
                            <span>⏱ Horas por día:</span><span className="font-bold">{horasPorDia.toFixed(1)} h</span>
                            <span>📅 Días por semana:</span><span className="font-bold">{formData.horario.dias.length}</span>
                            <span>📆 Horas por semana:</span><span className="font-bold">{horasPorSemana.toFixed(1)} h</span>
                            {horasPrograma && <><span>🎓 Horas del programa:</span><span className="font-bold">{horasPrograma} h</span></>}
                            {semanasTotal && <><span>🗓 Semanas necesarias:</span><span className="font-bold">{semanasTotal}</span></>}
                            {mesesTotal && <><span>🗓 Meses aproximados:</span><span className="font-bold">{mesesTotal}</span></>}
                          </div>
                        </div>
                      );
                    })()}
                  </>
                )}
                {formData.es_campesena && (
                  <div className="bg-[#FFFBEB] border-2 border-[#FFD966] rounded-2xl p-4 text-amber-700 text-center">
                    Las ofertas campesinas no requieren horario fijo.
                  </div>
                )}
              </div>
            )}

            {/* Botones de navegación */}
            <div className="flex justify-between mt-10 pt-6 border-t border-gray-200">
              {activeTab !== 'programa' && (
                <button type="button" onClick={prevTab} className="px-8 py-3 bg-gray-500 text-white rounded-2xl font-bold hover:bg-gray-600 transition-all shadow-md hover:shadow-lg">
                  ← Anterior
                </button>
              )}
              {activeTab !== 'horario' ? (
                <button type="button" onClick={nextTab} className="px-8 py-3 bg-[#00643C] text-white rounded-2xl font-bold hover:bg-[#004d2e] transition-all shadow-md hover:shadow-lg ml-auto">
                  Siguiente →
                </button>
              ) : (
                <button type="submit" disabled={loading} className="px-8 py-3 bg-[#00643C] text-white rounded-2xl font-bold hover:bg-[#004d2e] transition-all shadow-md hover:shadow-lg ml-auto flex items-center gap-2">
                  {loading ? (
                    <>
                      <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                      </svg>
                      Creando...
                    </>
                  ) : (
                    <>✅ Crear oferta</>
                  )}
                </button>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default CrearOferta;
